    def sign(v):
        return 0 if v == 0 else (1 if v > 0 else -1)

    def clamp_move(x, y, tx, ty):
        return [sign(tx - x), sign(ty - y)]

    def safe_pos(v):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return None

    def choose_nearest(items, x, y):
        best = None
        best_d = None
        for item in items:
            p = safe_pos(item)
            if p is None:
                continue
            px, py = p
            d = abs(px - x) + abs(py - y)
            if best is None or d < best_d:
                best = (px, py)
                best_d = d
        return best

